package com.bedlessfighter.necroManager.commands;
import com.bedlessfighter.necroManager.managers.*;import org.bukkit.Bukkit;import org.bukkit.command.*;import org.bukkit.entity.Player;import org.jetbrains.annotations.NotNull;import java.util.*;
public final class ReplyCommand implements CommandExecutor {
 @Override public boolean onCommand(@NotNull CommandSender s,@NotNull Command c,@NotNull String label, @NotNull String[] a){if(!(s instanceof Player p)){MessageManager.send(s,"messages.player-required","&cOnly players can reply.");return true;}if(a.length==0){MessageManager.sendRaw(s,"&cUsage: /reply <message>");return true;}if(!PermissionManager.has(s,"necromanager.msg")){MessageManager.send(s,"messages.no-perm","&cNo permission.");return true;}UUID id=ChatSocialManager.replyTarget(p.getUniqueId());Player t=id==null?null:Bukkit.getPlayer(id);if(t==null){MessageManager.sendRaw(s,"&cNobody to reply to.");return true;}if(ChatSocialManager.ignores(t.getUniqueId(),p.getUniqueId())){MessageManager.sendRaw(s,"&cThat player is ignoring you.");return true;}String m=String.join(" ",a);ChatSocialManager.reply(p.getUniqueId(),t.getUniqueId());ChatSocialManager.reply(t.getUniqueId(),p.getUniqueId());MessageManager.sendRaw(p,"&d[You -> "+t.getName()+"] &f"+m);MessageManager.sendRaw(t,"&d["+p.getName()+" -> You] &f"+m);for(Player x:Bukkit.getOnlinePlayers())if(!x.equals(p)&&!x.equals(t)&&ChatSocialManager.spying(x.getUniqueId())&&PermissionManager.has(x,"necromanager.socialspy"))MessageManager.sendRaw(x,"&8[Spy] "+p.getName()+" -> "+t.getName()+": "+m);return true;}
}